#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per
# SKU. Every catalog SKU must appear, including SKUs with no movements
# that day (SKU-9 is in the catalog and may never appear in movements.log).
awk 'BEGIN { for (i = 1; i <= 9; i++) net["SKU-" i] = 0 }
     { net[$1] += ($2 == "receipt" ? $3 : -$3) }
     END { for (sku in net) print sku, net[sku] }' \
    movements.log | sort > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per
# SKU that appears in movements.log, plus every catalog SKU (SKU-9 is in
# the catalog even when it has no movements that day).
awk 'BEGIN { net["SKU-9"] = 0 }
     { net[$1] += ($2 == "receipt" ? $3 : -$3) }
     END { for (sku in net) print sku, net[sku] }' \
    movements.log | sort > stock.txt
